        </div>
      </div>
    );
  }

  return (
    <div className="page">
      <div className="page-head">
        <div>
          <h2>{t("agent.title")}</h2>
          <p>{t("agent.subtitle")}</p>
        </div>
        {capabilities ? <ProviderBadge capabilities={capabilities} /> : null}
      </div>

